                    return False
            return True
        elif y1 == y2:
            for x in range(min(x1, x2) + 1, max(x1, x2)):
                if grid[x][y1] == '.':
                    return False
            return True
        return False

    # Find all painted squares
    painted_squares = []
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '#':
                painted_squares.append((i, j))

    # If there's only one painted square, it's already disconnected
    if len(painted_squares) == 1:
